protected SourceDocumentAmountMap calculateSourceDocumentAmountMap()
{
    SourceDocumentAmountMap standardMap = next calculateSourceDocumentAmountMap();

    VendPackingSlipTrans vendPackingSlipTrans = VendPackingSlipTrans::findBySourceDocumentLine(this.parmSourceDocumentLine().RecId);

    if (!vendPackingSlipTrans.RecId || !PdsGlobal::pdsIsCWItem(vendPackingSlipTrans.ItemId))
    {
        return standardMap;
    }

    PurchLine             purchLine           = vendPackingSlipTrans.purchLine();
    CostPriceNonMonetary  inventItemBasePrice = purchLine.metPurchLine().InventItemBasePrice;

    if (!inventItemBasePrice)
    {
        return standardMap;
    }

    CurrencyExchangeHelper currencyExchangeHelper = CurrencyExchangeHelper::newExchangeDate(
        Ledger::current(),
        vendPackingSlipTrans.DeliveryDate);
    currencyExchangeHelper.parmErrorType(AifErrorType::Exception);

    Amount newExtendedPrice = currencyExchangeHelper.calculateAccountingToTransaction(
        purchLine.CurrencyCode,
        inventItemBasePrice * vendPackingSlipTrans.InventQty,
        true);

    SourceDocumentAmountMap           newMap  = SourceDocumentAmountMap::construct();
    SourceDocumentAmountMapEnumerator mapEnum = standardMap.getEnumerator();

    while (mapEnum.moveNext())
    {
        SourceDocumentAmount sourceDocumentAmount = mapEnum.currentValue();

        if (mapEnum.currentKey() == MonetaryAmount::ExtendedPrice)
        {
            sourceDocumentAmount.parmAmount(newExtendedPrice);
        }

        newMap.insert(sourceDocumentAmount);
    }

    return newMap;
}
